(window.GGReadingsData = window.GGReadingsData || {})["poem3"] = [{"id":"poem-longfellow-nature","title":"Nature","by":"Henry Wadsworth Longfellow","year":1878,"trad":["all"],"type":"poem","occasion":["dying","evening"],"text":"As a fond mother, when the day is o'er,\nLeads by the hand her little child to bed,\nHalf willing, half reluctant to be led,\nAnd leave his broken playthings on the floor,\nStill gazing at them through the open door,\nNor wholly reassured and comforted\nBy promises of others in their stead,\nWhich, though more splendid, may not please him more;\nSo Nature deals with us, and takes away\nOur playthings one by one, and by the hand\nLeads us to rest so gently, that we go\nScarce knowing if we wish to go or stay,\nBeing too full of sleep to understand\nHow far the unknown transcends the what we know.","note":"Read softly at the bedside in the last days.","voice":"brian","source":{"name":"The Complete Poetical Works of Henry Wadsworth Longfellow","url":"https://www.gutenberg.org/ebooks/1365"},"rights":"pd","pd":"published 1878; Longfellow died 1882; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-longfellow-childrens-hour","title":"The Children's Hour","by":"Henry Wadsworth Longfellow","year":1860,"trad":["all"],"type":"poem","occasion":["home","evening"],"text":"Between the dark and the daylight,\nWhen the night is beginning to lower,\nComes a pause in the day's occupations,\nThat is known as the Children's Hour.\n\nI hear in the chamber above me\nThe patter of little feet,\nThe sound of a door that is opened,\nAnd voices soft and sweet.\n\nFrom my study I see in the lamplight,\nDescending the broad hall stair,\nGrave Alice, and laughing Allegra,\nAnd Edith with golden hair.\n\nA whisper, and then a silence:\nYet I know by their merry eyes\nThey are plotting and planning together\nTo take me by surprise.\n\nA sudden rush from the stairway,\nA sudden raid from the hall!\nBy three doors left unguarded\nThey enter my castle wall!\n\nThey climb up into my turret\nO'er the arms and back of my chair;\nIf I try to escape, they surround me;\nThey seem to be everywhere.\n\nThey almost devour me with kisses,\nTheir arms about me entwine,\nTill I think of the Bishop of Bingen\nIn his Mouse-Tower on the Rhine!\n\nDo you think, o blue-eyed banditti,\nBecause you have scaled the wall,\nSuch an old mustache as I am\nIs not a match for you all!\n\nI have you fast in my fortress,\nAnd will not let you depart,\nBut put you down into the dungeon\nIn the round-tower of my heart.\n\nAnd there will I keep you forever,\nYes, forever and a day,\nTill the walls shall crumble to ruin,\nAnd moulder in dust away!","note":"Read at a house blessing or a family gathering.","voice":"brian","source":{"name":"The Complete Poetical Works of Henry Wadsworth Longfellow","url":"https://www.gutenberg.org/ebooks/1365"},"rights":"pd","pd":"published 1860; Longfellow died 1882; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-longfellow-arrow-and-song","title":"The Arrow and the Song","by":"Henry Wadsworth Longfellow","year":1845,"trad":["all"],"type":"poem","occasion":["daily","celebration"],"text":"I shot an arrow into the air,\nIt fell to earth, I knew not where;\nFor, so swiftly it flew, the sight\nCould not follow it in its flight.\n\nI breathed a song into the air,\nIt fell to earth, I knew not where;\nFor who has sight so keen and strong,\nThat it can follow the flight of song?\n\nLong, long afterward, in an oak\nI found the arrow, still unbroke;\nAnd the song, from beginning to end,\nI found again in the heart of a friend.","note":"Read to honor friendship and the good we send into the world.","voice":"brian","source":{"name":"The Complete Poetical Works of Henry Wadsworth Longfellow","url":"https://www.gutenberg.org/ebooks/1365"},"rights":"pd","pd":"published 1845; Longfellow died 1882; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-longfellow-day-is-done","title":"The Day Is Done","by":"Henry Wadsworth Longfellow","year":1845,"trad":["all"],"type":"poem","occasion":["evening","peace"],"text":"The day is done, and the darkness\nFalls from the wings of Night,\nAs a feather is wafted downward\nFrom an eagle in his flight.\n\nI see the lights of the village\nGleam through the rain and the mist,\nAnd a feeling of sadness comes o'er me\nThat my soul cannot resist:\n\nA feeling of sadness and longing,\nThat is not akin to pain,\nAnd resembles sorrow only\nAs the mist resembles the rain.\n\nCome, read to me some poem,\nSome simple and heartfelt lay,\nThat shall soothe this restless feeling,\nAnd banish the thoughts of day.\n\nNot from the grand old masters,\nNot from the bards sublime,\nWhose distant footsteps echo\nThrough the corridors of Time.\n\nFor, like strains of martial music,\nTheir mighty thoughts suggest\nLife's endless toil and endeavor;\nAnd to-night I long for rest.\n\nRead from some humbler poet,\nWhose songs gushed from his heart,\nAs showers from the clouds of summer,\nOr tears from the eyelids start;\n\nWho, through long days of labor,\nAnd nights devoid of ease,\nStill heard in his soul the music\nOf wonderful melodies.\n\nSuch songs have power to quiet\nThe restless pulse of care,\nAnd come like the benediction\nThat follows after prayer.\n\nThen read from the treasured volume\nThe poem of thy choice,\nAnd lend to the rhyme of the poet\nThe beauty of thy voice.\n\nAnd the night shall be filled with music\nAnd the cares, that infest the day,\nShall fold their tents, like the Arabs,\nAnd as silently steal away.","note":"Read in the evening as the day comes to rest.","voice":"brian","source":{"name":"The Complete Poetical Works of Henry Wadsworth Longfellow","url":"https://www.gutenberg.org/ebooks/1365"},"rights":"pd","pd":"published 1845; Longfellow died 1882; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-longfellow-footsteps-of-angels","title":"Footsteps of Angels","by":"Henry Wadsworth Longfellow","year":1839,"trad":["all"],"type":"poem","occasion":["grief","evening"],"text":"When the hours of Day are numbered,\nAnd the voices of the Night\nWake the better soul, that slumbered,\nTo a holy, calm delight;\n\nEre the evening lamps are lighted,\nAnd, like phantoms grim and tall,\nShadows from the fitful firelight\nDance upon the parlor wall;\n\nThen the forms of the departed\nEnter at the open door;\nThe beloved, the true-hearted,\nCome to visit me once more;\n\nHe, the young and strong, who cherished\nNoble longings for the strife,\nBy the roadside fell and perished,\nWeary with the march of life!\n\nThey, the holy ones and weakly,\nWho the cross of suffering bore,\nFolded their pale hands so meekly,\nSpake with us on earth no more!\n\nAnd with them the Being Beauteous,\nWho unto my youth was given,\nMore than all things else to love me,\nAnd is now a saint in heaven.\n\nWith a slow and noiseless footstep\nComes that messenger divine,\nTakes the vacant chair beside me,\nLays her gentle hand in mine.\n\nAnd she sits and gazes at me\nWith those deep and tender eyes,\nLike the stars, so still and saint-like,\nLooking downward from the skies.\n\nUttered not, yet comprehended,\nIs the spirit's voiceless prayer,\nSoft rebukes, in blessings ended,\nBreathing from her lips of air.\n\nOh, though oft depressed and lonely,\nAll my fears are laid aside,\nIf I but remember only\nSuch as these have lived and died!","note":"Shared with someone carrying fresh grief.","voice":"brian","source":{"name":"The Complete Poetical Works of Henry Wadsworth Longfellow","url":"https://www.gutenberg.org/ebooks/1365"},"rights":"pd","pd":"published 1839; Longfellow died 1882; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-longfellow-two-angels","title":"The Two Angels","by":"Henry Wadsworth Longfellow","year":1858,"trad":["all"],"type":"poem","occasion":["birth","dying","grief"],"text":"Two angels, one of Life and one of Death,\nPassed o'er our village as the morning broke;\nThe dawn was on their faces, and beneath,\nThe sombre houses hearsed with plumes of smoke.\n\nTheir attitude and aspect were the same,\nAlike their features and their robes of white;\nBut one was crowned with amaranth, as with flame,\nAnd one with asphodels, like flakes of light.\n\nI saw them pause on their celestial way;\nThen said I, with deep fear and doubt oppressed,\n\"Beat not so loud, my heart, lest thou betray\nThe place where thy beloved are at rest!\"\n\nAnd he who wore the crown of asphodels,\nDescending, at my door began to knock,\nAnd my soul sank within me, as in wells\nThe waters sink before an earthquake's shock.\n\nI recognized the nameless agony,\nThe terror and the tremor and the pain,\nThat oft before had filled or haunted me,\nAnd now returned with threefold strength again.\n\nThe door I opened to my heavenly guest,\nAnd listened, for I thought I heard God's voice;\nAnd, knowing whatsoe'er he sent was best,\nDared neither to lament nor to rejoice.\n\nThen with a smile, that filled the house with light,\n\"My errand is not Death, but Life,\" he said;\nAnd ere I answered, passing out of sight,\nOn his celestial embassy he sped.\n\n'T was at thy door, O friend! and not at mine,\nThe angel with the amaranthine wreath,\nPausing, descended, and with voice divine,\nWhispered a word that had a sound like Death.\n\nThen fell upon the house a sudden gloom,\nA shadow on those features fair and thin;\nAnd softly, from that hushed and darkened room,\nTwo angels issued, where but one went in.\n\nAll is of God! If he but wave his hand,\nThe mists collect, the rain falls thick and loud,\nTill, with a smile of light on sea and land,\nLo! he looks back from the departing cloud.\n\nAngels of Life and Death alike are his;\nWithout his leave they pass no threshold o'er;\nWho, then, would wish or dare, believing this,\nAgainst his messengers to shut the door?","note":"Read when a birth and a death arrive close together.","voice":"brian","source":{"name":"The Complete Poetical Works of Henry Wadsworth Longfellow","url":"https://www.gutenberg.org/ebooks/1365"},"rights":"pd","pd":"published 1858; Longfellow died 1882; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-longfellow-old-clock","title":"The Old Clock on the Stairs","by":"Henry Wadsworth Longfellow","year":1845,"trad":["all"],"type":"poem","occasion":["home","grief"],"text":"Somewhat back from the village street\nStands the old-fashioned country-seat.\nAcross its antique portico\nTall poplar-trees their shadows throw;\nAnd from its station in the hall\nAn ancient timepiece says to all, \"Forever, never!\nNever, forever!\"\n\nHalf-way up the stairs it stands,\nAnd points and beckons with its hands\nFrom its case of massive oak,\nLike a monk, who, under his cloak,\nCrosses himself, and sighs, alas!\nWith sorrowful voice to all who pass, \"Forever, never!\nNever, forever!\"\n\nBy day its voice is low and light;\nBut in the silent dead of night,\nDistinct as a passing footstep's fall,\nIt echoes along the vacant hall,\nAlong the ceiling, along the floor,\nAnd seems to say, at each chamber-door, \"Forever, never!\nNever, forever!\"\n\nThrough days of sorrow and of mirth,\nThrough days of death and days of birth,\nThrough every swift vicissitude\nOf changeful time, unchanged it has stood,\nAnd as if, like God, it all things saw,\nIt calmly repeats those words of awe, \"Forever, never!\nNever, forever!\"\n\nIn that mansion used to be\nFree-hearted Hospitality;\nHis great fires up the chimney roared;\nThe stranger feasted at his board;\nBut, like the skeleton at the feast,\nThat warning timepiece never ceased, \"Forever, never!\nNever, forever!\"\n\nThere groups of merry children played,\nThere youths and maidens dreaming strayed;\nO precious hours! O golden prime,\nAnd affluence of love and time!\nEven as a Miser counts his gold,\nThose hours the ancient timepiece told, \"Forever, never!\nNever, forever!\"\n\nFrom that chamber, clothed in white,\nThe bride came forth on her wedding night;\nThere, in that silent room below,\nThe dead lay in his shroud of snow;\nAnd in the hush that followed the prayer,\nWas heard the old clock on the stair, \"Forever, never!\nNever, forever!\"\n\nAll are scattered now and fled,\nSome are married, some are dead;\nAnd when I ask, with throbs of pain.\n\"Ah! when shall they all meet again?\"\nAs in the days long since gone by,\nThe ancient timepiece makes reply, \"Forever, never!\nNever, forever!\"\n\nNever here, forever there,\nWhere all parting, pain, and care,\nAnd death, and time shall disappear, Forever there, but never here!\nThe horologe of Eternity\nSayeth this incessantly, \"Forever, never!\nNever, forever!\"","note":"Read at a house blessing or a family gathering.","voice":"brian","source":{"name":"The Complete Poetical Works of Henry Wadsworth Longfellow","url":"https://www.gutenberg.org/ebooks/1365"},"rights":"pd","pd":"published 1845; Longfellow died 1882; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-longfellow-cross-of-snow","title":"The Cross of Snow","by":"Henry Wadsworth Longfellow","year":1886,"trad":["all"],"type":"poem","occasion":["grief"],"text":"In the long, sleepless watches of the night,\nA gentle face, the face of one long dead,\nLooks at me from the wall, where round its head\nThe night-lamp casts a halo of pale light.\nHere in this room she died; and soul more white\nNever through martyrdom of fire was led\nTo its repose; nor can in books be read\nThe legend of a life more benedight.\nThere is a mountain in the distant West\nThat, sun-defying, in its deep ravines\nDisplays a cross of snow upon its side.\nSuch is the cross I wear upon my breast\nThese eighteen years, through all the changing scenes\nAnd seasons, changeless since the day she died.","note":"Read for a widow or widower in a long grief.","voice":"brian","source":{"name":"The Complete Poetical Works of Henry Wadsworth Longfellow","url":"https://www.gutenberg.org/ebooks/1365"},"rights":"pd","pd":"published 1886; Longfellow died 1882; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-longfellow-the-builders","title":"The Builders","by":"Henry Wadsworth Longfellow","year":1849,"trad":["all"],"type":"poem","occasion":["daily","celebration"],"text":"All are architects of Fate,\nWorking in these walls of Time;\nSome with massive deeds and great,\nSome with ornaments of rhyme.\n\nNothing useless is, or low;\nEach thing in its place is best;\nAnd what seems but idle show\nStrengthens and supports the rest.\n\nFor the structure that we raise,\nTime is with materials filled;\nOur to-days and yesterdays\nAre the blocks with which we build.\n\nTruly shape and fashion these;\nLeave no yawning gaps between;\nThink not, because no man sees,\nSuch things will remain unseen.\n\nIn the elder days of Art,\nBuilders wrought with greatest care\nEach minute and unseen part;\nFor the Gods see everywhere.\n\nLet us do our work as well,\nBoth the unseen and the seen;\nMake the house, where Gods may dwell,\nBeautiful, entire, and clean.\n\nElse our lives are incomplete,\nStanding in these walls of Time,\nBroken stairways, where the feet\nStumble as they seek to climb.\n\nBuild to-day, then, strong and sure,\nWith a firm and ample base;\nAnd ascending and secure\nShall to-morrow find its place.\n\nThus alone can we attain\nTo those turrets, where the eye\nSees the world as one vast plain,\nAnd one boundless reach of sky.","note":"Read at a celebration of life to honor a life well lived.","voice":"brian","source":{"name":"The Complete Poetical Works of Henry Wadsworth Longfellow","url":"https://www.gutenberg.org/ebooks/1365"},"rights":"pd","pd":"published 1849; Longfellow died 1882; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-whittier-at-last","title":"At Last","by":"John Greenleaf Whittier","year":1882,"trad":["christian","quaker"],"type":"poem","occasion":["dying"],"text":"When on my day of life the night is falling,\nAnd, in the winds from unsunned spaces blown,\nI hear far voices out of darkness calling\nMy feet to paths unknown,\n\nThou who hast made my home of life so pleasant,\nLeave not its tenant when its walls decay;\nO Love Divine, O Helper ever present,\nBe Thou my strength and stay!\n\nBe near me when all else is from me drifting\nEarth, sky, home's pictures, days of shade and shine,\nAnd kindly faces to my own uplifting\nThe love which answers mine.\n\nI have but Thee, my Father! let Thy spirit\nBe with me then to comfort and uphold;\nNo gate of pearl, no branch of palm I merit,\nNor street of shining gold.\n\nSuffice it if, my good and ill unreckoned,\nAnd both forgiven through Thy abounding grace,\nI find myself by hands familiar beckoned\nUnto my fitting place.\n\nSome humble door among Thy many mansions,\nSome sheltering shade where sin and striving cease,\nAnd flows forever through heaven's green expansions\nThe river of Thy peace.\n\nThere, from the music round about me stealing,\nI fain would learn the new and holy song,\nAnd find at last, beneath Thy trees of healing,\nThe life for which I long.","note":"Read softly at the bedside in the last days.","voice":"brian","source":{"name":"The Works of John Greenleaf Whittier, Volume II","url":"https://www.gutenberg.org/ebooks/9574"},"rights":"pd","pd":"published 1882; Whittier died 1892; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-whittier-eternal-goodness","title":"The Eternal Goodness (Closing Stanzas)","by":"John Greenleaf Whittier","year":1865,"trad":["christian","quaker"],"type":"poem","occasion":["dying","hope","funeral"],"text":"I know not what the future hath\nOf marvel or surprise,\nAssured alone that life and death\nHis mercy underlies.\n\nAnd if my heart and flesh are weak\nTo bear an untried pain,\nThe bruised reed He will not break,\nBut strengthen and sustain.\n\nNo offering of my own I have,\nNor works my faith to prove;\nI can but give the gifts He gave,\nAnd plead His love for love.\n\nAnd so beside the Silent Sea\nI wait the muffled oar;\nNo harm from Him can come to me\nOn ocean or on shore.\n\nI know not where His islands lift\nTheir fronded palms in air;\nI only know I cannot drift\nBeyond His love and care.\n\nO brothers! if my faith is vain,\nIf hopes like these betray,\nPray for me that my feet may gain\nThe sure and safer way.\n\nAnd Thou, O Lord! by whom are seen\nThy creatures as they be,\nForgive me if too close I lean\nMy human heart on Thee!","note":"Read softly at the bedside in the last days.","voice":"brian","source":{"name":"The Works of John Greenleaf Whittier, Volume II","url":"https://www.gutenberg.org/ebooks/9574"},"rights":"pd","pd":"published 1865; Whittier died 1892; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-whittier-my-psalm","title":"My Psalm","by":"John Greenleaf Whittier","year":1859,"trad":["christian","quaker"],"type":"poem","occasion":["dying","gratitude"],"text":"I mourn no more my vanished years\nBeneath a tender rain,\nAn April rain of smiles and tears,\nMy heart is young again.\n\nThe west-winds blow, and, singing low,\nI hear the glad streams run;\nThe windows of my soul I throw\nWide open to the sun.\n\nNo longer forward nor behind\nI look in hope or fear;\nBut, grateful, take the good I find,\nThe best of now and here.\n\nI plough no more a desert land,\nTo harvest weed and tare;\nThe manna dropping from God's hand\nRebukes my painful care.\n\nI break my pilgrim staff, I lay\nAside the toiling oar;\nThe angel sought so far away\nI welcome at my door.\n\nThe airs of spring may never play\nAmong the ripening corn,\nNor freshness of the flowers of May\nBlow through the autumn morn.\n\nYet shall the blue-eyed gentian look\nThrough fringed lids to heaven,\nAnd the pale aster in the brook\nShall see its image given; The woods shall wear their robes of praise,\nThe south-wind softly sigh,\nAnd sweet, calm days in golden haze\nMelt down the amber sky.\n\nNot less shall manly deed and word\nRebuke an age of wrong;\nThe graven flowers that wreathe the sword\nMake not the blade less strong.\n\nBut smiting hands shall learn to heal, To build as to destroy;\nNor less my heart for others feel\nThat I the more enjoy.\n\nAll as God wills, who wisely heeds\nTo give or to withhold,\nAnd knoweth more of all my needs\nThan all my prayers have told.\n\nEnough that blessings undeserved\nHave marked my erring track;\nThat wheresoe'er my feet have swerved,\nHis chastening turned me back;\n\nThat more and more a Providence\nOf love is understood,\nMaking the springs of time and sense\nSweet with eternal good; That death seems but a covered way\nWhich opens into light,\nWherein no blinded child can stray\nBeyond the Father's sight;\n\nThat care and trial seem at last,\nThrough Memory's sunset air,\nLike mountain-ranges overpast,\nIn purple distance fair;\n\nThat all the jarring notes of life\nSeem blending in a psalm,\nAnd all the angles of its strife\nSlow rounding into calm.\n\nAnd so the shadows fall apart,\nAnd so the west-winds play;\nAnd all the windows of my heart\nI open to the day.","note":"Read at a milestone birthday or a gathering honoring an elder.","voice":"brian","source":{"name":"The Works of John Greenleaf Whittier, Volume II","url":"https://www.gutenberg.org/ebooks/9574"},"rights":"pd","pd":"published 1859; Whittier died 1892; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-lowell-first-snow-fall","title":"The First Snow-Fall","by":"James Russell Lowell","year":1849,"trad":["all"],"type":"poem","occasion":["grief"],"text":"The snow had begun in the gloaming,\nAnd busily all the night\nHad been heaping field and highway\nWith a silence deep and white.\n\nEvery pine and fir and hemlock\nWore ermine too dear for an earl,\nAnd the poorest twig on the elm-tree\nWas ridged inch deep with pearl.\n\nFrom sheds new-roofed with Carrara\nCame Chanticleer's muffled crow,\nThe stiff rails softened to swan's-down,\nAnd still fluttered down the snow.\n\nI stood and watched by the window\nThe noiseless work of the sky,\nAnd the sudden flurries of snowbirds,\nLike brown leaves whirling by.\n\nI thought of a mound in sweet Auburn\nWhere a little headstone stood;\nHow the flakes were folding it gently,\nAs did robins the babes in the wood.\n\nUp spoke our own little Mabel,\nSaying, 'Father, who makes it snow?'\nAnd I told of the good All-father\nWho cares for us here below.\n\nAgain I looked at the snow-fall,\nAnd thought of the leaden sky\nThat arched o'er our first great sorrow,\nWhen that mound was heaped so high.\n\nI remembered the gradual patience\nThat fell from that cloud like snow,\nFlake by flake, healing and hiding\nThe scar that renewed our woe.\n\nAnd again to the child I whispered,\n'The snow that husheth all,\nDarling, the merciful Father\nAlone can make it fall!'\n\nThen, with eyes that saw not, I kissed her:\nAnd she, kissing back, could not know\nThat my kiss was given to her sister,\nFolded close under deepening snow.","note":"Read gently for parents grieving a child.","voice":"brian","source":{"name":"The Complete Poetical Works of James Russell Lowell","url":"https://www.gutenberg.org/ebooks/13310"},"rights":"pd","pd":"published 1849; Lowell died 1891; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-lowell-she-came-and-went","title":"She Came and Went","by":"James Russell Lowell","year":1849,"trad":["all"],"type":"poem","occasion":["grief","birth"],"text":"She came and went\n\nAs a twig trembles, which a bird\nLights on to sing, then leaves unbent,\nSo is my memory thrilled and stirred; I only know she came and went.\n\nAs clasps some lake, by gusts unriven,\nThe blue dome's measureless content, So my soul held, that moment's heaven; I only know she came and went.\n\nAs, at one bound, our swift spring heaps\nThe orchards full of bloom and scent,\nSo clove her May my wintry sleeps; I only know she came and went.\n\nAn angel stood and met my gaze,\nThrough the low doorway of my tent;\nThe tent is struck, the vision stays; I only know she came and went\n\nOh, when the room grows slowly dim,\nAnd life's last oil is nearly spent,\nOne gush of light these eyes will brim,\nOnly to think she came and went.","note":"Read gently for parents grieving a child.","voice":"brian","source":{"name":"The Complete Poetical Works of James Russell Lowell","url":"https://www.gutenberg.org/ebooks/13310"},"rights":"pd","pd":"published 1849; Lowell died 1891; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-lowell-the-changeling","title":"The Changeling","by":"James Russell Lowell","year":1848,"trad":["all"],"type":"poem","occasion":["grief"],"text":"I had a little daughter,\nAnd she was given to me\nTo lead me gently backward\nTo the Heavenly Father's knee,\nThat I, by the force of nature.\nMight in some dim wise divine\nThe depth of his infinite patience\nTo this wayward soul of mine.\n\nI know not how others saw her,\nBut to me she was wholly fair,\nAnd the light of the heaven she came from\nStill lingered and gleamed in her hair;\nFor it was as wavy and golden,\nAnd as many changes took,\nAs the shadows of sun-gilt ripples\nOn the yellow bed of a brook.\n\nTo what can I liken her smiling\nUpon me, her kneeling lover,\nHow it leaped from her lips to her eyelids,\nAnd dimpled her wholly over,\nTill her outstretched hands smiled also,\nAnd I almost seemed to see\nThe very heart of her mother\nSending sun through her veins to me!\n\nShe had been with us scarce a twelvemonth,\nAnd it hardly seemed a day,\nWhen a troop of wandering angels\nStole my little daughter away;\nOr perhaps those heavenly Zingari\nBut loosed the hampering strings,\nAnd when they had opened her cage-door.\nMy little bird used her wings.\n\nBut they left in her stead a changeling\nA little angel child,\nThat seems like her bud in full blossom,\nAnd smiles as she never smiled:\nWhen I wake in the morning, I see it\nWhere she always used to lie,\nAnd I feel as weak as a violet\nAlone 'neath the awful sky.\n\nAs weak, yet as trustful also;\nFor the whole year long I see\nAll the wonders of faithful Nature\nStill worked for the love of me;\nWinds wander, and dews drip earthward,\nRain falls, suns rise and set,\nEarth whirls, and all but to prosper\nA poor little violet.\n\nThis child is not mine as the first was,\nI cannot sing it to rest,\nI cannot lift it up fatherly\nAnd bliss it upon my breast:\nYet it lies in my little one's cradle\nAnd sits in my little one's chair,\nAnd the light of the heaven she's gone to\nTransfigures its golden hair.","note":"Read gently for parents grieving a child.","voice":"brian","source":{"name":"The Complete Poetical Works of James Russell Lowell","url":"https://www.gutenberg.org/ebooks/13310"},"rights":"pd","pd":"published 1848; Lowell died 1891; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-bryant-thanatopsis-close","title":"So Live (from Thanatopsis)","by":"William Cullen Bryant","year":1821,"trad":["all"],"type":"poem","occasion":["funeral","dying"],"text":"So live, that when thy summons comes to join\nThe innumerable caravan, that moves\nTo that mysterious realm, where each shall take\nHis chamber in the silent halls of death,\nThou go not like the quarry-slave at night,\nScourged to his dungeon, but, sustained and soothed\nBy an unfaltering trust, approach thy grave,\nLike one who wraps the drapery of his couch\nAbout him, and lies down to pleasant dreams.","note":"Read at a funeral or memorial to honor a life.","voice":"brian","source":{"name":"Poems by William Cullen Bryant","url":"https://www.gutenberg.org/ebooks/16341"},"rights":"pd","pd":"published 1821; Bryant died 1878; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-bryant-to-a-waterfowl","title":"To a Waterfowl","by":"William Cullen Bryant","year":1818,"trad":["all"],"type":"poem","occasion":["hope","dying","nature"],"text":"Whither, midst falling dew,\nWhile glow the heavens with the last steps of day,\nFar, through their rosy depths, dost thou pursue\nThy solitary way?\n\nVainly the fowler's eye\nMight mark thy distant flight to do thee wrong,\nAs, darkly painted on the crimson sky,\nThy figure floats along.\n\nSeek'st thou the plashy brink\nOf weedy lake, or marge of river wide,\nOr where the rocking billows rise and sink\nOn the chafed ocean side?\n\nThere is a Power whose care\nTeaches thy way along that pathless coast, The desert and illimitable air, Lone wandering, but not lost.\n\nAll day thy wings have fanned,\nAt that far height, the cold, thin atmosphere,\nYet stoop not, weary, to the welcome land,\nThough the dark night is near.\n\nAnd soon that toil shall end;\nSoon shalt thou find a summer home, and rest,\nAnd scream among thy fellows; reeds shall bend,\nSoon, o'er thy sheltered nest.\n\nThou'rt gone, the abyss of heaven\nHath swallowed up thy form; yet, on my heart\nDeeply hath sunk the lesson thou hast given,\nAnd shall not soon depart.\n\nHe who, from zone to zone,\nGuides through the boundless sky thy certain flight,\nIn the long way that I must tread alone,\nWill lead my steps aright.","note":"Read when someone needs courage and hope.","voice":"brian","source":{"name":"Poems by William Cullen Bryant","url":"https://www.gutenberg.org/ebooks/16341"},"rights":"pd","pd":"published 1818; Bryant died 1878; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-bryant-fringed-gentian","title":"To the Fringed Gentian","by":"William Cullen Bryant","year":1832,"trad":["all"],"type":"poem","occasion":["season","dying"],"text":"Thou blossom bright with autumn dew,\nAnd coloured with the heaven's own blue,\nThat openest when the quiet light\nSucceeds the keen and frosty night.\n\nThou comest not when violets lean\nO'er wandering brooks and springs unseen,\nOr columbines, in purple dressed,\nNod o'er the ground-bird's hidden nest.\n\nThou waitest late and com'st alone,\nWhen woods are bare and birds are flown,\nAnd frosts and shortening days portend\nThe aged year is near his end.\n\nThen doth thy sweet and quiet eye\nLook through its fringes to the sky,\nBlue, blue, as if that sky let fall\nA flower from its cerulean wall.\n\nI would that thus, when I shall see\nThe hour of death draw near to me,\nHope, blossoming within my heart,\nMay look to heaven as I depart.","note":"Read to mark the turning of the seasons.","voice":"brian","source":{"name":"Poems by William Cullen Bryant","url":"https://www.gutenberg.org/ebooks/16341"},"rights":"pd","pd":"published 1832; Bryant died 1878; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-bryant-death-of-the-flowers","title":"The Death of the Flowers","by":"William Cullen Bryant","year":1825,"trad":["all"],"type":"poem","occasion":["season","grief"],"text":"The melancholy days are come, the saddest of the year,\nOf wailing winds, and naked woods, and meadows brown and sear.\nHeaped in the hollows of the grove, the autumn leaves lie dead;\nThey rustle to the eddying gust, and to the rabbit's tread.\nThe robin and the wren are flown, and from the shrubs the jay,\nAnd from the wood-top calls the crow through all the gloomy day.\n\nWhere are the flowers, the fair young flowers, that lately sprang and stood\nIn brighter light, and softer airs, a beauteous sisterhood?\nAlas! they all are in their graves, the gentle race, of flowers\nAre lying in their lowly beds, with the fair and good of ours.\nThe rain is falling where they lie, but the cold November rain\nCalls not from out the gloomy earth the lovely ones again.\n\nThe wind-flower and the violet, they perished long ago,\nAnd the brier-rose and the orchis died amid the summer glow;\nBut on the hill the golden-rod, and the aster in the wood,\nAnd the yellow sun-flower by the brook in autumn beauty stood,\nTill fell the frost from the clear cold heaven, as falls the plague on men,\nAnd the brightness of their smile was gone, from upland, glade, and glen.\n\nAnd now, when comes the calm mild day, as still such days will come,\nTo call the squirrel and the bee from out their winter home;\nWhen the sound of dropping nuts is heard, though all the trees are still,\nAnd twinkle in the smoky light the waters of the rill,\nThe south wind searches for the flowers whose fragrance late he bore,\nAnd sighs to find them in the wood and by the stream no more.\n\nAnd then I think of one who in her youthful beauty died,\nThe fair meek blossom that grew up and faded by my side:\nIn the cold moist earth we laid her, when the forest cast the leaf,\nAnd we wept that one so lovely should have a life so brief:\nYet not unmeet it was that one, like that young friend of ours,\nSo gentle and so beautiful, should perish with the flowers.","note":"Read to mark the turning of the seasons.","voice":"brian","source":{"name":"Poems by William Cullen Bryant","url":"https://www.gutenberg.org/ebooks/16341"},"rights":"pd","pd":"published 1825; Bryant died 1878; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-lanier-ballad-of-trees","title":"A Ballad of Trees and the Master","by":"Sidney Lanier","year":1880,"trad":["christian"],"type":"poem","occasion":["dying","comfort","nature"],"text":"Into the woods my Master went,\nClean forspent, forspent.\nInto the woods my Master came,\nForspent with love and shame.\nBut the olives they were not blind to Him,\nThe little gray leaves were kind to Him:\nThe thorn-tree had a mind to Him\nWhen into the woods He came.\n\nOut of the woods my Master went,\nAnd He was well content.\nOut of the woods my Master came,\nContent with death and shame.\nWhen Death and Shame would woo Him last,\nFrom under the trees they drew Him last:\n'Twas on a tree they slew Him, last\nWhen out of the woods He came.","note":"Read in a garden or woods during Holy Week or a time of trial.","voice":"brian","source":{"name":"The Poems of Sidney Lanier","url":"https://www.gutenberg.org/ebooks/579"},"rights":"pd","pd":"published 1880; Lanier died 1881; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-housman-loveliest-of-trees","title":"Loveliest of Trees","by":"A. E. Housman","year":1896,"trad":["all"],"type":"poem","occasion":["season","nature"],"text":"Loveliest of trees, the cherry now\nIs hung with bloom along the bough,\nAnd stands about the woodland ride\nWearing white for Eastertide.\n\nNow, of my threescore years and ten,\nTwenty will not come again,\nAnd take from seventy springs a score,\nIt only leaves me fifty more.\n\nAnd since to look at things in bloom\nFifty springs are little room,\nAbout the woodlands I will go\nTo see the cherry hung with snow.","note":"Read to mark the turning of the seasons.","voice":"brian","source":{"name":"A Shropshire Lad (1896)","url":"https://www.gutenberg.org/ebooks/5720"},"rights":"pd","pd":"published 1896; Housman died 1936; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-housman-athlete-dying-young","title":"To an Athlete Dying Young","by":"A. E. Housman","year":1896,"trad":["all"],"type":"poem","occasion":["funeral","grief"],"text":"The time you won your town the race\nWe chaired you through the market-place;\nMan and boy stood cheering by,\nAnd home we brought you shoulder-high.\n\nTo-day, the road all runners come,\nShoulder-high we bring you home,\nAnd set you at your threshold down,\nTownsman of a stiller town.\n\nSmart lad, to slip betimes away\nFrom fields where glory does not stay\nAnd early though the laurel grows\nIt withers quicker than the rose.\n\nEyes the shady night has shut\nCannot see the record cut,\nAnd silence sounds no worse than cheers\nAfter earth has stopped the ears:\n\nNow you will not swell the rout\nOf lads that wore their honours out,\nRunners whom renown outran\nAnd the name died before the man.\n\nSo set, before its echoes fade,\nThe fleet foot on the sill of shade,\nAnd hold to the low lintel up\nThe still-defended challenge-cup.\n\nAnd round that early-laurelled head\nWill flock to gaze the strengthless dead,\nAnd find unwithered on its curls\nThe garland briefer than a girl's.","note":"Read at a memorial for a young person.","voice":"brian","source":{"name":"A Shropshire Lad (1896)","url":"https://www.gutenberg.org/ebooks/5720"},"rights":"pd","pd":"published 1896; Housman died 1936; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-housman-with-rue","title":"With Rue My Heart Is Laden","by":"A. E. Housman","year":1896,"trad":["all"],"type":"poem","occasion":["grief"],"text":"With rue my heart is laden\nFor golden friends I had,\nFor many a rose-lipt maiden\nAnd many a lightfoot lad.\n\nBy brooks too broad for leaping\nThe lightfoot boys are laid;\nThe rose-lipt girls are sleeping\nIn fields where roses fade.","note":"Shared with someone carrying fresh grief.","voice":"brian","source":{"name":"A Shropshire Lad (1896)","url":"https://www.gutenberg.org/ebooks/5720"},"rights":"pd","pd":"published 1896; Housman died 1936; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-kilmer-trees","title":"Trees","by":"Joyce Kilmer","year":1913,"trad":["all"],"type":"poem","occasion":["nature"],"text":"I think that I shall never see\nA poem lovely as a tree.\n\nA tree whose hungry mouth is prest\nAgainst the earth's sweet flowing breast;\n\nA tree that looks at God all day,\nAnd lifts her leafy arms to pray;\n\nA tree that may in Summer wear\nA nest of robins in her hair;\n\nUpon whose bosom snow has lain;\nWho intimately lives with rain.\n\nPoems are made by fools like me,\nBut only God can make a tree.","note":"Read outdoors, on a walk, or at a gathering in nature.","voice":"brian","source":{"name":"Trees and Other Poems (1914)","url":"https://www.gutenberg.org/ebooks/263"},"rights":"pd","pd":"published 1913; Kilmer died 1918; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-vandyke-work","title":"Work","by":"Henry van Dyke","year":1904,"trad":["all"],"type":"poem","occasion":["daily","celebration"],"text":"Let me but do my work from day to day,\nIn field or forest, at the desk or loom,\nIn roaring market-place or tranquil room;\nLet me but find it in my heart to say,\nWhen vagrant wishes beckon me astray,\n\"This is my work; my blessing, not my doom;\nOf all who live, I am the one by whom\nThis work can best be done in the right way.\"\n\nThen shall I see it not too great, nor small,\nTo suit my spirit and to prove my powers;\nThen shall I cheerful greet the labouring hours,\nAnd cheerful turn, when the long shadows fall\nAt eventide, to play and love and rest,\nBecause I know for me my work is best.","note":"Read at a retirement or to honor a life of good work.","voice":"brian","source":{"name":"The Poems of Henry van Dyke (1920)","url":"https://www.gutenberg.org/ebooks/16229"},"rights":"pd","pd":"published 1904; Dyke died 1933; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-vandyke-four-things","title":"Four Things","by":"Henry van Dyke","year":1904,"trad":["all"],"type":"poem","occasion":["daily"],"text":"Four things a man must learn to do\nIf he would make his record true:\nTo think without confusion clearly;\nTo love his fellow-men sincerely;\nTo act from honest motives purely;\nTo trust in God and Heaven securely.","note":"Read at a graduation or a coming of age.","voice":"brian","source":{"name":"The Poems of Henry van Dyke (1920)","url":"https://www.gutenberg.org/ebooks/16229"},"rights":"pd","pd":"published 1904; Dyke died 1933; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-vandyke-life","title":"Life","by":"Henry van Dyke","year":1904,"trad":["all"],"type":"poem","occasion":["dying","hope"],"text":"Let me but live my life from year to year,\nWith forward face and unreluctant soul;\nNot hurrying to, nor turning from, the goal;\nNot mourning for the things that disappear\nIn the dim past, nor holding back in fear\nFrom what the future veils; but with a whole\nAnd happy heart, that pays its toll\nTo Youth and Age, and travels on with cheer.\n\nSo let the way wind up the hill or down,\nO'er rough or smooth, the journey will be joy:\nStill seeking what I sought when but a boy,\nNew friendship, high adventure, and a crown,\nMy heart will keep the courage of the quest,\nAnd hope the road's last turn will be the best.","note":"Read at a milestone birthday or a gathering honoring an elder.","voice":"brian","source":{"name":"The Poems of Henry van Dyke (1920)","url":"https://www.gutenberg.org/ebooks/16229"},"rights":"pd","pd":"published 1904; Dyke died 1933; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-vandyke-if-all-the-skies","title":"If All the Skies","by":"Henry van Dyke","year":1904,"trad":["all"],"type":"poem","occasion":["comfort","hope"],"text":"If all the skies were sunshine,\nOur faces would be fain\nTo feel once more upon them\nThe cooling plash of rain.\n\nIf all the world were music,\nOur hearts would often long\nFor one sweet strain of silence.\nTo break the endless song.\n\nIf life were always merry,\nOur souls would seek relief,\nAnd rest from weary laughter\nIn the quiet arms of grief.","note":"Shared as comfort in a hard season.","voice":"brian","source":{"name":"The Poems of Henry van Dyke (1920)","url":"https://www.gutenberg.org/ebooks/16229"},"rights":"pd","pd":"published 1904; Dyke died 1933; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-lazarus-new-colossus","title":"The New Colossus","by":"Emma Lazarus","year":1883,"trad":["all"],"type":"poem","occasion":["hope","home"],"text":"Not like the brazen giant of Greek fame,\nWith conquering limbs astride from land to land;\nHere at our sea-washed, sunset gates shall stand\nA mighty woman with a torch, whose flame\nIs the imprisoned lightning, and her name\nMother of Exiles. From her beacon-hand\nGlows world-wide welcome; her mild eyes command\nThe air-bridged harbor that twin cities frame.\n\"Keep, ancient lands, your storied pomp!\" cries she\nWith silent lips. \"Give me your tired, your poor,\nYour huddled masses yearning to be free,\nThe wretched refuse of your teeming shore.\nSend these, the homeless, tempest-tost to me,\nI lift my lamp beside the golden door!\"","note":"Read to welcome newcomers to a community.","voice":"brian","source":{"name":"The Poems of Emma Lazarus, Volume 1 (1889)","url":"https://www.gutenberg.org/ebooks/3295"},"rights":"pd","pd":"published 1883; Lazarus died 1887; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-foss-house-by-the-road","title":"The House by the Side of the Road","by":"Sam Walter Foss","year":1897,"trad":["all"],"type":"poem","occasion":["funeral","home","celebration"],"text":"There are hermit souls that live withdrawn\nIn the peace of their self-content;\nThere are souls, like stars, that dwell apart,\nIn a fellowless firmament;\nThere are pioneer souls that blaze their paths\nWhere highways never ran;\nBut let me live by the side of the road\nAnd be a friend to man.\n\nLet me live in a house by the side of the road,\nWhere the race of men go by,\nThe men who are good and the men who are bad,\nAs good and as bad as I.\nI would not sit in the scorner's seat,\nOr hurl the cynic's ban;\nLet me live in a house by the side of the road\nAnd be a friend to man.\n\nI see from my house by the side of the road,\nBy the side of the highway of life,\nThe men who press with the ardor of hope,\nThe men who are faint with the strife.\nBut I turn not away from their smiles nor their tears,\nBoth parts of an infinite plan;\nLet me live in my house by the side of the road\nAnd be a friend to man.\n\nI know there are brook-gladdened meadows ahead\nAnd mountains of wearisome height;\nThat the road passes on through the long afternoon\nAnd stretches away to the night.\nBut still I rejoice when the travelers rejoice,\nAnd weep with the strangers that moan.\nNor live in my house by the side of the road\nLike a man who dwells alone.\n\nLet me live in my house by the side of the road\nWhere the race of men go by;\nThey are good, they are bad, they are weak, they are strong,\nWise, foolish, so am I.\nThen why should I sit in the scorner's seat,\nOr hurl the cynic's ban?\nLet me live in my house by the side of the road\nAnd be a friend to man.","note":"Read at a celebration of life to honor a life well lived.","voice":"brian","source":{"name":"Poems Teachers Ask For (1925)","url":"https://www.gutenberg.org/ebooks/18909"},"rights":"pd","pd":"published 1897; Foss died 1911; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-field-little-boy-blue","title":"Little Boy Blue","by":"Eugene Field","year":1888,"trad":["all"],"type":"poem","occasion":["grief"],"text":"The little toy dog is covered with dust,\nBut sturdy and stanch he stands;\nAnd the little toy soldier is red with rust,\nAnd his musket moulds in his hands.\nTime was when the little toy dog was new\nAnd the soldier was passing fair,\nAnd that was the time when our Little Boy Blue\nKissed them and put them there.\n\n\"Now, don't you go till I come,\" he said,\n\"And don't you make any noise!\"\nSo toddling off to his trundle-bed\nHe dreamt of the pretty toys.\nAnd as he was dreaming, an angel song\nAwakened our Little Boy Blue, Oh, the years are many, the years are long,\nBut the little toy friends are true.\n\nAy, faithful to Little Boy Blue they stand,\nEach in the same old place,\nAwaiting the touch of a little hand,\nThe smile of a little face.\nAnd they wonder, as waiting these long years through,\nIn the dust of that little chair,\nWhat has become of our little Boy Blue\nSince he kissed them and put them there.","note":"Read gently for parents grieving a child.","voice":"brian","source":{"name":"Poems Teachers Ask For (1925)","url":"https://www.gutenberg.org/ebooks/18909"},"rights":"pd","pd":"published 1888; Field died 1895; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-carruth-each-in-his-own-tongue","title":"Each in His Own Tongue","by":"William Herbert Carruth","year":1895,"trad":["all"],"type":"poem","occasion":["nature","daily"],"text":"A fire-mist and a planet,\nA crystal and a cell,\nA jellyfish and a saurian,\nAnd caves where the cavemen dwell;\nThen a sense of law and beauty,\nAnd a face turned from the clod, Some call it Evolution,\nAnd others call it God.\n\nA haze in the far horizon,\nThe infinite, tender sky;\nThe ripe, rich tints of the cornfields,\nAnd the wild geese sailing high;\nAnd all over upland and lowland\nThe charm of the goldenrod, Some of us call it Nature,\nAnd others call it God.\n\nLike tides on a crescent sea-beach,\nWhen the moon is new and thin,\nInto our hearts high yearnings\nCome welling and surging in, Come from the mystic ocean.\nWhose rim no foot has trod, Some of us call it Longing,\nAnd others call it God.\n\nA picket frozen on duty,\nA mother starved for her brood,\nSocrates drinking the hemlock,\nAnd Jesus on the rood;\nThe millions who, humble and nameless,\nThe straight, hard pathway trod, Some call it Consecration,\nAnd others call it God.","note":"Read at an interfaith gathering, honoring the many names for the holy.","voice":"brian","source":{"name":"Poems Teachers Ask For (1925)","url":"https://www.gutenberg.org/ebooks/18909"},"rights":"pd","pd":"published 1895; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-holmes-chambered-nautilus","title":"The Chambered Nautilus","by":"Oliver Wendell Holmes","year":1858,"trad":["all"],"type":"poem","occasion":["celebration","hope","dying"],"text":"This is the ship of pearl, which, poets feign,\nSails the unshadowed main, The venturous bark that flings\nOn the sweet summer wind its purpled wings\nIn gulfs enchanted, where the Siren sings,\nAnd coral reefs lie bare,\nWhere the cold sea-maids rise to sun their streaming hair.\n\nIts webs of living gauze no more unfurl;\nWrecked is the ship of pearl!\nAnd every chambered cell,\nWhere its dim dreaming life was wont to dwell,\nAs the frail tenant shaped his growing shell,\nBefore thee lies revealed, Its irised ceiling rent, its sunless crypt unsealed!\n\nYear after year beheld the silent toil\nThat spread his lustrous coil;\nStill, as the spiral grew,\nHe left the past year's dwelling for the new,\nStole with soft step its shining archway through,\nBuilt up its idle door,\nStretched in his last-found home, and knew the old no more.\n\nThanks for the heavenly message brought by thee,\nChild of the wandering sea,\nCast from her lap, forlorn!\nFrom thy dead lips a clearer note is born\nThan ever Triton blew from wreathed horn!\nWhile on mine ear it rings,\nThrough the deep caves of thought I hear a voice that sings: Build thee more stately mansions, O my soul,\nAs the swift seasons roll!\nLeave thy low-vaulted past!\nLet each new temple, nobler than the last,\nShut thee from heaven with a dome more vast,\nTill thou at length art free,\nLeaving thine outgrown shell by life's unresting sea!","note":"Read at a milestone of growth, a graduation, or a life celebration.","voice":"brian","source":{"name":"Poems Teachers Ask For (1925)","url":"https://www.gutenberg.org/ebooks/18909"},"rights":"pd","pd":"published 1858; Holmes died 1894; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-holland-gradatim","title":"Gradatim","by":"Josiah Gilbert Holland","year":1872,"trad":["all"],"type":"poem","occasion":["hope","daily"],"text":"Heaven is not reached at a single bound;\nBut we build the ladder by which we rise\nFrom the lowly earth to the vaulted skies,\nAnd we mount to the summit round by round,\n\nI count this thing to be grandly true:\nThat a noble deed is a step toward God,\nLifting a soul from the common sod\nTo a purer air and a broader view.\n\nWe rise by things that are under our feet;\nBy what we have mastered of good and gain,\nBy the pride deposed and the passion slain,\nAnd the vanquished ills that we hourly meet.\n\nWe hope, we aspire, we resolve, we trust,\nWhen the morning calls us to life and light;\nBut our hearts grow weary, and ere he night\nOur lives are trailing the sordid dust.\n\nWe hope, we resolve, we aspire, we pray,\nAnd we think that we mount the air on wings,\nBeyond the recall of sensual things,\nWhile our feet still cling to the heavy clay.\n\nOnly in dreams is a ladder thrown\nFrom the weary earth to the sapphire walls;\nBut the dreams depart, and the vision falls,\nAnd the sleeper awakes on his pillow of stone.\n\nHeaven is not reached at a single bound;\nBut we build the ladder by which we rise\nFrom the lowly earth to the vaulted skies,\nAnd we mount to the summit round by round.","note":"Read when someone needs courage and hope.","voice":"brian","source":{"name":"Poems Teachers Ask For (1925)","url":"https://www.gutenberg.org/ebooks/18909"},"rights":"pd","pd":"published 1872; Holland died 1881; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-clough-say-not-the-struggle","title":"Say Not the Struggle Nought Availeth","by":"Arthur Hugh Clough","year":1862,"trad":["all"],"type":"poem","occasion":["hope","healing"],"text":"Say not the struggle nought availeth,\nThe labor and the wounds are vain,\nThe enemy faints not, nor faileth,\nAnd as things have been they remain.\n\nIf hopes were dupes, fears may be liars;\nIt may be, in yon smoke concealed,\nYour comrades chase e'en now the fliers,\nAnd, but for you, possess the field.\n\nFor while the tired waves, vainly breaking,\nSeem here no painful inch to gain,\nFar back, through creeks and inlets making,\nComes silent, flooding in, the main,\n\nAnd not by eastern windows only,\nWhen daylight comes, comes in the light,\nIn front, the sun climbs slow, how slowly,\nBut westward, look, the land is bright.","note":"Read when someone needs courage and hope.","voice":"brian","source":{"name":"Poems Teachers Ask For (1925)","url":"https://www.gutenberg.org/ebooks/18909"},"rights":"pd","pd":"published 1862; Clough died 1861; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-allen-rock-me-to-sleep","title":"Rock Me to Sleep","by":"Elizabeth Akers Allen","year":1860,"trad":["all"],"type":"poem","occasion":["grief"],"text":"Backward, turn backward, O time, in your flight,\nMake me a child again just for tonight!\nMother, come back from the echoless shore,\nTake me again to your heart as of yore;\nKiss from my forehead the furrows of care,\nSmooth the few silver threads out of my hair;\nOver my slumbers your loving watch keep; Rock me to sleep, mother, rock me to sleep.\n\nBackward, flow backward, O tide of the years!\nI am so weary of toil and of tears, Toil without recompense, tears all in vain, Take them, and give me my childhood again!\nI have grown weary of dust and decay, Weary of flinging my soul-wealth away;\nWeary of sowing for others to reap; Rock me to sleep, mother, rock me to sleep.\n\nTired of the hollow, the base, the untrue,\nMother, O mother, my heart calls for you!\nMany a summer the grass has grown green,\nBlossomed and faded, our faces between;\nYet with strong yearning and passionate pain\nLong I to-night for your presence again.\nCome from the silence so long and so deep; Rock me to sleep, mother, rock me to sleep.\n\nOver my heart, in the days that are flown,\nNo love like mother-love ever has shone;\nNo other worship abides and endures,\nFaithful, unselfish and patient, like yours;\nNone like a mother can charm away pain\nFrom the sick soul and the world-weary brain.\nSlumber's soft calms o'er my heavy lids creep; Rock me to sleep, mother, rock me to sleep.\n\nCome, let your brown hair, just lighted with gold,\nFall on your shoulders again as of old;\nLet it drop over my forehead to-night,\nShading my faint eyes away from the light;\nFor with its sunny-edged shadows once more\nHaply will throng the sweet visions of yore;\nLovingly, softly, its bright billows sweep; Rock me to sleep, mother, rock me to sleep.\n\nMother, dear mother, the years have been long\nSince I last listened your lullaby song;\nSing, then, and unto my soul it shall seem\nWomanhood's years have been only a dream.\nClasped to your breast in a loving embrace,\nWith your light lashes just sweeping my face,\nNever hereafter to wake or to weep; Rock me to sleep, mother, rock me to sleep.","note":"Read in memory of a mother.","voice":"brian","source":{"name":"Poems Teachers Ask For (1925)","url":"https://www.gutenberg.org/ebooks/18909"},"rights":"pd","pd":"published 1860; Allen died 1911; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-bond-a-perfect-day","title":"A Perfect Day","by":"Carrie Jacobs-Bond","year":1910,"trad":["all"],"type":"song","occasion":["funeral","evening","celebration"],"text":"When you come to the end of a perfect day\nAnd you sit alone with your thought\nWhile the chimes ring out with a carol gay\nFor the joy that the day has brought,\nDo you think what the end of a perfect day\nCan mean to a tired heart?\nWhen the sun goes down with a flaming ray\nAnd the dear friends have to part?\n\nWell, this is the end of a perfect day,\nNear the end of a journey, too;\nBut it leaves a thought that is big and strong,\nWith a wish that is kind and true;\nFor mem'ry has painted this perfect day\nWith colors that never fade,\nAnd we find, at the end of a perfect day,\nThe soul of a friend we've made.","note":"Read at the close of a celebration of life or a happy day.","voice":"brian","source":{"name":"Poems Teachers Ask For (1925)","url":"https://www.gutenberg.org/ebooks/18909"},"rights":"pd","pd":"published 1910; Jacobs-Bond died 1946; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-tennyson-sweet-and-low","title":"Sweet and Low","by":"Alfred, Lord Tennyson","year":1850,"trad":["all"],"type":"poem","occasion":["birth","evening"],"text":"Sweet and low, sweet and low,\nWind of the western sea,\nLow, low, breathe and blow,\nWind of the western sea!\nOver the rolling waters go,\nCome from the dying moon, and blow,\nBlow him again to me;\nWhile my little one, while my pretty one, sleeps.\n\nSleep and rest, sleep and rest,\nFather will come to thee soon;\nRest, rest, on mother's breast,\nFather will come to thee soon;\nFather will come to his babe in the nest,\nSilver sails all out of the west\nUnder the silver moon;\nSleep, my little one, sleep, my pretty one, sleep.","note":"Read softly as a lullaby.","voice":"brian","source":{"name":"Poems Teachers Ask For (1925)","url":"https://www.gutenberg.org/ebooks/18909"},"rights":"pd","pd":"published 1850; Tennyson died 1892; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-rands-wonderful-world","title":"The Wonderful World","by":"William Brighty Rands","year":1868,"trad":["all"],"type":"poem","occasion":["nature","birth"],"text":"Great, wide, beautiful, wonderful World,\nWith the wonderful water round you curled,\nAnd the wonderful grass upon your breast,\nWorld, you are beautifully drest.\n\nThe wonderful air is over me.\nAnd the wonderful wind is shaking the tree,\nIt walks on the water, and whirls the mills,\nAnd talks to itself on the top of the hills.\n\nYou friendly Earth, how far do you go,\nWith the wheat-fields that nod and the rivers that flow,\nWith cities and gardens, and cliffs and isles,\nAnd people upon you for thousands of miles?\n\nAh! you are so great, and I am so small,\nI hardly can think of you, World, at all;\nAnd yet, when I said my prayers today,\nA whisper within me seemed to say:\n\"You are more than the Earth, though you are such a dot!\nYou can love and think, and the Earth can not.\"","note":"Read aloud with children at bedtime or at home.","voice":"brian","source":{"name":"Poems Teachers Ask For (1925)","url":"https://www.gutenberg.org/ebooks/18909"},"rights":"pd","pd":"published 1868; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-babcock-be-strong","title":"Be Strong","by":"Maltbie D. Babcock","year":1901,"trad":["christian"],"type":"poem","occasion":["hope","healing"],"text":"Be strong!\nWe are not here to play, to dream, to drift;\nWe have hard work to do, and loads to lift;\nShun not the struggle, face it; 'tis God's gift.\n\nBe strong!\nSay not, \"The days are evil. Who's to blame?\"\nAnd fold the hands and acquiesce, oh shame!\nStand up, speak out, and bravely, in God's name.\n\nBe strong!\nIt matters not how deep intrenched the wrong.\nHow hard the battle goes, the day how long;\nFaint not, fight on! To-morrow comes the song.","note":"Read when someone needs courage and hope.","voice":"brian","source":{"name":"Poems Teachers Ask For (1925)","url":"https://www.gutenberg.org/ebooks/18909"},"rights":"pd","pd":"published 1901; Babcock died 1901; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-jackson-october","title":"October's Bright Blue Weather","by":"Helen Hunt Jackson","year":1876,"trad":["all"],"type":"poem","occasion":["season","nature"],"text":"O suns and skies and clouds of June,\nAnd flowers of June together,\nYe cannot rival for one hour\nOctober's bright blue weather;\n\nWhen loud the bumblebee makes haste,\nBelated, thriftless vagrant,\nAnd goldenrod is dying fast,\nAnd lanes with grapes are fragrant;\n\nWhen gentians roll their fringes tight\nTo save them for the morning,\nAnd chestnuts fall from satin burrs\nWithout a sound of warning;\n\nWhen on the ground red apples lie\nIn piles like jewels shining,\nAnd redder still on old stone walls\nAre leaves of woodbine twining;\n\nWhen all the lovely wayside things\nTheir white-winged seeds are sowing,\nAnd in the fields, still green and fair,\nLate aftermaths are growing;\n\nWhen springs run low, and on the brooks,\nIn idle, golden freighting,\nBright leaves sink noiseless in the hush\nOf woods, for winter waiting;\n\nWhen comrades seek sweet country haunts,\nBy twos and threes together,\nAnd count like misers hour by hour,\nOctober's bright blue weather.\n\nO suns and skies and flowers of June,\nCount all your boasts together,\nLove loveth best of all the year\nOctober's bright blue weather.","note":"Read to mark the turning of the seasons.","voice":"brian","source":{"name":"Poems Teachers Ask For (1925)","url":"https://www.gutenberg.org/ebooks/18909"},"rights":"pd","pd":"published 1876; Jackson died 1885; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-banks-what-i-live-for","title":"What I Live For","by":"George Linnaeus Banks","year":1855,"trad":["all"],"type":"poem","occasion":["daily","celebration"],"text":"I live for those who love me,\nWhose hearts are kind and true,\nFor the heaven that smiles above me,\nAnd awaits my spirit, too;\nFor the human ties that bind me,\nFor the task by God assigned me,\nFor the bright hopes left behind me,\nAnd the good that I can do.\n\nI live to learn their story\nWho've suffered for my sake,\nTo emulate their glory,\nAnd to follow in their wake;\nBards, patriots, martyrs, sages,\nThe noble of all ages,\nWhose deeds crowd history's pages,\nAnd Time's great volume make.\n\nI live to hold communion\nWith all that is divine,\nTo feel there is a union\n'Twixt Nature's heart and mine;\nTo profit by affliction,\nReap truths from fields of fiction,\nGrow wiser from conviction,\nAnd fulfill each grand design.\n\nI live to hail that season,\nBy gifted minds foretold,\nWhen men shall rule by reason,\nAnd not alone by gold;\nWhen man to man united,\nAnd every wrong thing righted,\nThe whole world shall be lighted\nAs Eden was of old.\n\nI live for those who love me,\nFor those who know me true,\nFor the heaven that smiles above me,\nAnd awaits my spirit, too;\nFor the cause that lacks assistance,\nFor the wrong that needs resistance,\nFor the future in the distance,\nAnd the good that I can do.","note":"Read at a celebration of life to honor a life well lived.","voice":"brian","source":{"name":"Poems Teachers Ask For (1925)","url":"https://www.gutenberg.org/ebooks/18909"},"rights":"pd","pd":"published 1855; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-poe-annabel-lee","title":"Annabel Lee","by":"Edgar Allan Poe","year":1849,"trad":["all"],"type":"poem","occasion":["grief","wedding"],"text":"It was many and many a year ago,\nIn a kingdom by the sea,\nThat a maiden there lived whom you may know\nBy the name of Annabel Lee;\nAnd this maiden she lived with no other thought\nThan to love and be loved by me.\n\nI was a child, and she was a child,\nIn this kingdom by the sea,\nBut we loved with a love that was more than love,\nI and my Annabel Lee;\nWith a love that the winged seraphs of heaven\nCoveted her and me.\n\nAnd this was the reason that, long ago,\nIn this kingdom by the sea,\nA wind blew out of a cloud, chilling\nMy beautiful Annabel Lee;\nSo that her highborn kinsmen came\nAnd bore her away from me,\nTo shut her up in a sepulchre\nIn this kingdom by the sea.\n\nThe angels, not half so happy in heaven,\nWent envying her and me;\nYes! that was the reason (as all men know,\nIn this kingdom by the sea)\nThat the wind came out of the cloud by night,\nChilling and killing my Annabel Lee.\n\nBut our love it was stronger by far than the love\nOf those who were older than we,\nOf many far wiser than we;\nAnd neither the angels in heaven above,\nNor the demons down under the sea,\nCan ever dissever my soul from the soul\nOf the beautiful Annabel Lee:\n\nFor the moon never beams, without bringing me dreams\nOf the beautiful Annabel Lee;\nAnd the stars never rise, but I feel the bright eyes\nOf the beautiful Annabel Lee:\nAnd so all the night-tide, I lie down by the side\nOf my darling, my darling, my life and my bride,\nIn her sepulchre there by the sea,\nIn her tomb by the sounding sea.","note":"Read for a love that outlasts death.","voice":"brian","source":{"name":"Poems Teachers Ask For, Book Two (1925)","url":"https://www.gutenberg.org/ebooks/19469"},"rights":"pd","pd":"published 1849; Poe died 1849; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-dromgoole-bridge-builder","title":"The Bridge Builder","by":"Attributed to Will Allen Dromgoole","year":1900,"trad":["all"],"type":"poem","occasion":["funeral","celebration"],"text":"An old man going a lone highway,\nCame, at the evening cold and gray,\nTo a chasm vast and deep and wide,\nThe old man crossed in the twilight dim,\nThe sullen stream had no fear for him;\nBut he turned when safe on the other side\nAnd built a bridge to span the tide.\n\n\"Old man,\" said a fellow pilgrim near,\n\"You are wasting your strength with building here;\nYour journey will end with the ending day,\nYon never again will pass this way;\nYou've crossed the chasm, deep and wide,\nWhy build this bridge at evening tide?\"\n\nThe builder lifted his old gray head;\n\"Good friend, in the path I have come,\" he said,\n\"There followed after me to-day\nA youth whose feet must pass this way.\nThis chasm that has been as naught to me\nTo that fair-haired youth may a pitfall be;\nHe, too, must cross in the twilight dim;\nGood friend, I am building this bridge for him!\"","note":"Read at a memorial or retirement to honor someone who built for others.","voice":"brian","source":{"name":"Poems Teachers Ask For, Book Two (1925)","url":"https://www.gutenberg.org/ebooks/19469"},"rights":"pd","pd":"published 1900; Dromgoole died 1934; US public domain (published 1930 or earlier); the 1925 source prints it as Anonymous","denom":[]},{"id":"poem-guest-home","title":"Home","by":"Edgar A. Guest","year":1916,"trad":["all"],"type":"poem","occasion":["home"],"text":"It takes a heap o' livin' in a house t' make it home,\nA heap o' sun an' shadder, an' ye sometimes have t' roam\nAfore ye really 'preciate the things ye left behind,\nAn' hunger fer 'em somehow, with 'em allus on yer mind.\nIt don't make any differunce how rich ye get t' be,\nHow much yer chairs an' tables cost, how great yer luxury;\nIt ain't home t' ye, though it be the palace of a king,\nUntil somehow yer soul is sort o' wrapped 'round everything.\n\nHome ain't a place that gold can buy or get up in a minute;\nAfore it's home there's got t' be a heap o' livin' in it:\nWithin the walls there's got t' be some babies born, and then\nRight there ye've got t' bring 'em up t' women good, an' men;\nAnd gradjerly, as time goes on ye find ye wouldn't part\nWith anything they ever used, they've grown into yer heart;\nThe old high chairs, the playthings, too, the little shoes they wore\nYe hoard; an' if ye could ye'd keep the thumbmarks on the door.\n\nYe've got t' weep t' make it home, ye've got t' sit and sigh\nAn' watch beside a loved one's bed, an' know that Death is nigh;\nAn' in the stillness o' the night t' see Death's angel come,\nAn' close the eyes o' her that smiled, an' leave her sweet voice dumb.\nFer these are scenes that grip the heart, an' when yer tears are dried,\nYe find the home is dearer than it was, an' sanctified;\nAn' tuggin' at ye always are the pleasant memories\nO' her that was an' is no more, ye can't escape from these.\n\nYe've got t' sing and dance fer years, ye've got t' romp an' play,\nAn' learn t' love the things ye have by usin' 'em each day;\nEven the roses 'round the porch must blossom year by year\nAfore they 'come a part o' ye, suggestin' someone dear\nWho used t' love 'em long ago, an' trained 'em jes' t' run\nThe way they do, so's they would get the early mornin' sun;\nYe've got t' love each brick an' stone from cellar up t' dome:\nIt takes a heap o' livin' in a house f' make it home.","note":"Read at a house blessing or a family gathering.","voice":"brian","source":{"name":"Poems Teachers Ask For, Book Two (1925)","url":"https://www.gutenberg.org/ebooks/19469"},"rights":"pd","pd":"published 1916; Guest died 1959; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-kilmer-house-with-nobody","title":"The House with Nobody in It","by":"Joyce Kilmer","year":1914,"trad":["all"],"type":"poem","occasion":["home","grief"],"text":"Whenever I walk to Suffern along the Erie track\nI go by a poor old farm-house with its shingles broken and black;\nI suppose I've passed it a hundred times, but I always stop for a minute\nAnd look at the house, the tragic house, the house with nobody in it.\n\nI've never seen a haunted house, but I hear there are such things;\nThat they hold the talk of spirits, their mirth and sorrowings.\nI know that house isn't haunted and I wish it were, I do,\nFor it wouldn't be so lonely if it had a ghost or two.\n\nThis house on the road to Suffern needs a dozen panes of glass,\nAnd somebody ought to weed the walk and take a scythe to the grass.\nIt needs new paint and shingles and vines should be trimmed and tied,\nBut what it needs most of all is some people living inside.\n\nIf I had a bit of money and all my debts were paid,\nI'd put a gang of men to work with brush and saw and spade.\nI'd buy that place and fix it up the way that it used to be,\nAnd I'd find some people who wanted a home and give it to them free.\n\nNow a new home standing empty with staring window and door\nLooks idle perhaps and foolish, like a hat on its block in the store,\nBut there's nothing mournful about it, it cannot be sad and lone\nFor the lack of something within it that it has never known.\n\nBut a house that has done what a house should do, a house that has\nsheltered life,\nThat has put its loving wooden arms around a man and his wife,\nA house that has echoed a baby's laugh and helped up his stumbling feet,\nIs the saddest sight, when it's left alone, that ever your eyes could meet.\n\nSo whenever I go to Suffern along the Erie track\nI never go by the empty house without stopping and looking back,\nYet it hurts me to look at the crumbling roof and the shutters fallen\napart,\nFor I can't help thinking the poor old house is a house with a broken\nheart.","note":"Read when a family home is being emptied or sold.","voice":"brian","source":{"name":"Poems Teachers Ask For, Book Two (1925)","url":"https://www.gutenberg.org/ebooks/19469"},"rights":"pd","pd":"published 1914; Kilmer died 1918; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-barbauld-life","title":"Life","by":"Anna Laetitia Barbauld","year":1825,"trad":["all"],"type":"poem","occasion":["dying","funeral"],"text":"Life! I know not what thou art,\nBut know that thou and I must part;\nAnd when, or how, or where we met\nI own to me's a secret yet.\n\nLife! we've been long together\nThrough pleasant and through cloudy weather;\n'Tis hard to part when friends are dear,\nPerhaps 'twill cost a sigh, a tear;\n\nThen steal away; give little warning,\nChoose thine own time;\nSay not Good Night, but in some brighter clime\nBid me Good Morning.","note":"Read softly at the bedside in the last days.","voice":"brian","source":{"name":"Poems Teachers Ask For, Book Two (1925)","url":"https://www.gutenberg.org/ebooks/19469"},"rights":"pd","pd":"published 1825; Barbauld died 1825; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-fletcher-land-of-beginning-again","title":"The Land of Beginning Again","by":"Louisa Fletcher","year":1911,"trad":["all"],"type":"poem","occasion":["forgiveness","hope"],"text":"I wish there were some wonderful place\nCalled the Land of Beginning Again,\nWhere all our mistakes and all our heartaches,\nAnd all our poor, selfish griefs\nCould be dropped, like a shabby old coat, at the door,\nAnd never put on again.\n\nI wish we could come on it all unaware,\nLike the hunter who finds a lost trail;\nAnd I wish that the one whom our blindness had done\nThe greatest injustice of all\nCould be at the gate like the old friend that waits\nFor the comrade he's gladdest to hail.\n\nWe would find the things we intended to do,\nBut forgot and remembered too late,\nLittle praises unspoken, little promises broken,\nAnd all of the thousand and one\nLittle duties neglected that might have perfected\nThe days of one less fortunate.\n\nIt wouldn't be possible not to be kind.\nIn the Land of Beginning Again;\nAnd the ones we misjudged and the ones whom we grudged\nTheir moments of victory here,\nWould find the grasp of our loving handclasp\nMore than penitent lips could explain.\n\nFor what had been hardest we'd know had been best,\nAnd what had seemed loss would be gain,\nFor there isn't a sting that will not take wing\nWhen we've faced it and laughed it away;\nAnd I think that the laughter is most what we're after,\nIn the Land of Beginning Again.\n\nSo I wish that there were some wonderful place\nCalled the Land of Beginning Again,\nWhere all our mistakes and all our heartaches,\nAnd all our poor, selfish griefs\nCould be dropped, like a ragged old coat, at the door,\nAnd never put on again.","note":"Read at a time of forgiveness or a fresh start.","voice":"brian","source":{"name":"Poems Teachers Ask For, Book Two (1925)","url":"https://www.gutenberg.org/ebooks/19469"},"rights":"pd","pd":"published 1911; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-holmes-last-leaf","title":"The Last Leaf","by":"Oliver Wendell Holmes","year":1831,"trad":["all"],"type":"poem","occasion":["dying","celebration"],"text":"I saw him once before,\nAs he passed by the door,\nAnd again\nThe pavement stones resound,\nAs he totters o'er the ground\nWith his cane.\n\nThey say that in his prime,\nEre the pruning-knife of Time\nCut him down,\nNot a better man was found\nBy the Crier on his round\nThrough the town.\n\nBut now he walks the streets,\nAnd he looks at all he meets\nSad and wan,\nAnd he shakes his feeble head,\nThat it seems as if he said\n\"They are gone.\"\n\nThe mossy marbles rest\nOn the lips that he has prest\nIn their bloom,\nAnd the names he loved to hear\nHave been carved for many a year\nOn the tomb.\n\nMy grandmamma has said, Poor old lady, she is dead\nLong ago, That he had a Roman nose,\nAnd his cheek was like a rose\nIn the snow.\n\nBut now his nose is thin,\nAnd it rests upon his chin.\nLike a staff,\nAnd a crook is in his back,\nAnd a melancholy crack\nIn his laugh.\n\nI know it is a sin\nFor me to sit and grin\nAt him here;\nBut the old three-cornered hat,\nAnd the breeches, and all that,\nAre so queer!\n\nAnd if I should live to be\nThe last leaf upon the tree\nIn the spring,\nLet them smile, as I do now,\nAt the old forsaken bough\nWhere I cling.","note":"Read at a milestone birthday or a gathering honoring an elder.","voice":"brian","source":{"name":"Poems Teachers Ask For, Book Two (1925)","url":"https://www.gutenberg.org/ebooks/19469"},"rights":"pd","pd":"published 1831; Holmes died 1894; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-tennyson-ring-out-wild-bells","title":"Ring Out, Wild Bells","by":"Alfred, Lord Tennyson","year":1850,"trad":["all"],"type":"poem","occasion":["season","hope","celebration"],"text":"Ring out, wild bells, to the wild sky,\nThe flying cloud, the frosty light:\nThe year is dying in the night;\nRing out, wild bells, and let him die.\n\nRing out the old, ring in the new,\nRing, happy bells, across the snow:\nThe year is going, let him go;\nRing out the false, ring in the true.\n\nRing out the grief that saps the mind,\nFor those that here we see no more;\nRing out the feud of rich and poor,\nRing in redress to all mankind.\n\nRing out a slowly dying cause,\nAnd ancient forms of party strife;\nRing in the nobler modes of life,\nWith sweeter manners, purer laws.\n\nRing out false pride in place and blood,\nThe civic slander and the spite;\nRing in the love of truth and right,\nRing in the common love of good.\n\nRing out old shapes of foul disease;\nRing out the narrowing lust of gold;\nRing out the thousand wars of old,\nRing in the thousand years of peace.\n\nRing in the valiant man and free,\nThe larger heart, the kindlier hand;\nRing out the darkness of the land,\nRing in the Christ that is to be.","note":"Read at the New Year.","voice":"brian","source":{"name":"Poems Teachers Ask For, Book Two (1925)","url":"https://www.gutenberg.org/ebooks/19469"},"rights":"pd","pd":"published 1850; Tennyson died 1892; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-cary-nearer-home","title":"Nearer Home","by":"Phoebe Cary","year":1852,"trad":["christian"],"type":"poem","occasion":["dying","hope"],"text":"One sweetly solemn thought\nComes to me o'er and o'er, I am nearer home to-day\nThan I've ever been before; Nearer my Father's house\nWhere the many mansions be,\nNearer the great white throne,\nNearer the jasper sea; Nearer the bound of life\nWhere we lay our burdens down;\nNearer leaving the cross,\nNearer gaining the crown.\n\nBut lying darkly between,\nWinding down through the night,\nIs the dim and unknown stream\nThat leads at last to the light.\n\nCloser and closer my steps\nCome to the dark abysm;\nCloser death to my lips\nPresses the awful chrism.\n\nFather, perfect my trust;\nStrengthen the might of my faith;\nLet me feel as I would when I stand\nOn the rock of the shore of death, Feel as I would when my feet\nAre slipping o'er the brink;\nFor it may be I am nearer home,\nNearer now than I think.","note":"Read softly at the bedside in the last days.","voice":"brian","source":{"name":"Poems Teachers Ask For, Book Two (1925)","url":"https://www.gutenberg.org/ebooks/19469"},"rights":"pd","pd":"published 1852; Cary died 1871; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-kinney-rain-on-the-roof","title":"Rain on the Roof","by":"Coates Kinney","year":1849,"trad":["all"],"type":"poem","occasion":["home","grief","evening"],"text":"When the humid showers gather over all the starry spheres,\nAnd the melancholy darkness gently weeps in rainy tears,\n'Tis a joy to press the pillow of a cottage chamber bed,\nAnd listen to the patter of the soft rain overhead.\n\nEvery tinkle on the shingles has an echo in the heart,\nAnd a thousand dreamy fancies into busy being start;\nAnd a thousand recollections weave their bright hues into woof,\nAs I listen to the patter of the soft rain on the roof.\n\nThere in fancy comes my mother, as she used to years agone,\nTo survey the infant sleepers ere she left them till the dawn.\nI can see her bending o'er me, as I listen to the strain\nWhich is played upon the shingles by the patter of the rain.\n\nThen my little seraph sister, with her wings and waving hair,\nAnd her bright-eyed, cherub brother, a serene, angelic pair,\nGlide around my wakeful pillow with their praise or mild reproof,\nAs I listen to the murmur of the soft rain on the roof.\n\nAnd another comes to thrill me with her eyes' delicious blue,\nI forget, as gazing on her, that her heart was all untrue,\nI remember that I loved her as I ne'er may love again,\nAnd my heart's quick pulses vibrate to the patter of the rain.\n\nThere is naught in art's bravuras that can work with such a spell,\nIn the spirit's pure, deep fountains, whence the holy passions swell,\nAs that melody of nature, that subdued, subduing strain,\nWhich is played upon the shingles by the patter of the rain!","note":"Read on a rainy evening of remembering.","voice":"brian","source":{"name":"Poems Teachers Ask For, Book Two (1925)","url":"https://www.gutenberg.org/ebooks/19469"},"rights":"pd","pd":"published 1849; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-stevenson-happy-thought","title":"Happy Thought","by":"Robert Louis Stevenson","year":1885,"trad":["all"],"type":"poem","occasion":["daily","gratitude"],"text":"The world is so full of a number of things,\nI'm sure we should all be as happy as kings.","note":"Read aloud with children at bedtime or at home.","voice":"brian","source":{"name":"A Child's Garden of Verses (1885)","url":"https://www.gutenberg.org/ebooks/136"},"rights":"pd","pd":"published 1885; Stevenson died 1894; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-stevenson-my-shadow","title":"My Shadow","by":"Robert Louis Stevenson","year":1885,"trad":["all"],"type":"poem","occasion":["home","daily"],"text":"I have a little shadow that goes in and out with me,\nAnd what can be the use of him is more than I can see.\nHe is very, very like me from the heels up to the head;\nAnd I see him jump before me, when I jump into my bed.\n\nThe funniest thing about him is the way he likes to grow,\nNot at all like proper children, which is always very slow;\nFor he sometimes shoots up taller like an india-rubber ball,\nAnd he sometimes goes so little that there's none of him at all.\n\nHe hasn't got a notion of how children ought to play,\nAnd can only make a fool of me in every sort of way.\nHe stays so close behind me, he's a coward you can see;\nI'd think shame to stick to nursie as that shadow sticks to me!\n\nOne morning, very early, before the sun was up,\nI rose and found the shining dew on every buttercup;\nBut my lazy little shadow, like an arrant sleepy-head,\nHad stayed at home behind me and was fast asleep in bed.","note":"Read aloud with children at bedtime or at home.","voice":"brian","source":{"name":"A Child's Garden of Verses (1885)","url":"https://www.gutenberg.org/ebooks/136"},"rights":"pd","pd":"published 1885; Stevenson died 1894; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-stevenson-land-of-counterpane","title":"The Land of Counterpane","by":"Robert Louis Stevenson","year":1885,"trad":["all"],"type":"poem","occasion":["healing","home"],"text":"When I was sick and lay a-bed,\nI had two pillows at my head,\nAnd all my toys beside me lay,\nTo keep me happy all the day.\n\nAnd sometimes for an hour or so\nI watched my leaden soldiers go,\nWith different uniforms and drills,\nAmong the bed-clothes, through the hills;\n\nAnd sometimes sent my ships in fleets\nAll up and down among the sheets;\nOr brought my trees and houses out,\nAnd planted cities all about.\n\nI was the giant great and still\nThat sits upon the pillow-hill,\nAnd sees before him, dale and plain,\nThe pleasant land of counterpane.","note":"Read with a child who is sick in bed.","voice":"brian","source":{"name":"A Child's Garden of Verses (1885)","url":"https://www.gutenberg.org/ebooks/136"},"rights":"pd","pd":"published 1885; Stevenson died 1894; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-stevenson-lamplighter","title":"The Lamplighter","by":"Robert Louis Stevenson","year":1885,"trad":["all"],"type":"poem","occasion":["evening","home"],"text":"My tea is nearly ready and the sun has left the sky.\nIt's time to take the window to see Leerie going by;\nFor every night at teatime and before you take your seat,\nWith lantern and with ladder he comes posting up the street.\n\nNow Tom would be a driver and Maria go to sea,\nAnd my papa's a banker and as rich as he can be;\nBut I, when I am stronger and can choose what I'm to do,\nO Leerie, I'll go round at night and light the lamps with you!\n\nFor we are very lucky, with a lamp before the door,\nAnd Leerie stops to light it as he lights so many more;\nAnd oh! before you hurry by with ladder and with light;\nO Leerie, see a little child and nod to him to-night!","note":"Read aloud with children at bedtime or at home.","voice":"brian","source":{"name":"A Child's Garden of Verses (1885)","url":"https://www.gutenberg.org/ebooks/136"},"rights":"pd","pd":"published 1885; Stevenson died 1894; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-stevenson-where-go-the-boats","title":"Where Go the Boats?","by":"Robert Louis Stevenson","year":1885,"trad":["all"],"type":"poem","occasion":["nature","home"],"text":"Dark brown is the river,\nGolden is the sand.\nIt flows along for ever,\nWith trees on either hand.\n\nGreen leaves a-floating,\nCastles of the foam,\nBoats of mine a-boating,\nWhere will all come home?\n\nOn goes the river\nAnd out past the mill,\nAway down the valley,\nAway down the hill.\n\nAway down the river,\nA hundred miles or more,\nOther little children\nShall bring my boats ashore.","note":"Read aloud with children at bedtime or at home.","voice":"brian","source":{"name":"A Child's Garden of Verses (1885)","url":"https://www.gutenberg.org/ebooks/136"},"rights":"pd","pd":"published 1885; Stevenson died 1894; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-stevenson-bed-in-summer","title":"Bed in Summer","by":"Robert Louis Stevenson","year":1885,"trad":["all"],"type":"poem","occasion":["evening","season"],"text":"In winter I get up at night\nAnd dress by yellow candle-light.\nIn summer quite the other way,\nI have to go to bed by day.\n\nI have to go to bed and see\nThe birds still hopping on the tree,\nOr hear the grown-up people's feet\nStill going past me in the street.\n\nAnd does it not seem hard to you,\nWhen all the sky is clear and blue,\nAnd I should like so much to play,\nTo have to go to bed by day?","note":"Read aloud with children at bedtime or at home.","voice":"brian","source":{"name":"A Child's Garden of Verses (1885)","url":"https://www.gutenberg.org/ebooks/136"},"rights":"pd","pd":"published 1885; Stevenson died 1894; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-stevenson-escape-at-bedtime","title":"Escape at Bedtime","by":"Robert Louis Stevenson","year":1885,"trad":["all"],"type":"poem","occasion":["evening","nature"],"text":"The lights from the parlour and kitchen shone out\nThrough the blinds and the windows and bars;\nAnd high overhead and all moving about,\nThere were thousands of millions of stars.\nThere ne'er were such thousands of leaves on a tree,\nNor of people in church or the Park,\nAs the crowds of the stars that looked down upon me,\nAnd that glittered and winked in the dark.\n\nThe Dog, and the Plough, and the Hunter, and all,\nAnd the star of the sailor, and Mars,\nThese shown in the sky, and the pail by the wall\nWould be half full of water and stars.\nThey saw me at last, and they chased me with cries,\nAnd they soon had me packed into bed;\nBut the glory kept shining and bright in my eyes,\nAnd the stars going round in my head.","note":"Read aloud with children at bedtime or at home.","voice":"brian","source":{"name":"A Child's Garden of Verses (1885)","url":"https://www.gutenberg.org/ebooks/136"},"rights":"pd","pd":"published 1885; Stevenson died 1894; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-stevenson-autumn-fires","title":"Autumn Fires","by":"Robert Louis Stevenson","year":1885,"trad":["all"],"type":"poem","occasion":["season"],"text":"In the other gardens\nAnd all up the vale,\nFrom the autumn bonfires\nSee the smoke trail!\n\nPleasant summer over\nAnd all the summer flowers,\nThe red fire blazes,\nThe grey smoke towers.\n\nSing a song of seasons!\nSomething bright in all!\nFlowers in the summer,\nFires in the fall!","note":"Read to mark the turning of the seasons.","voice":"brian","source":{"name":"A Child's Garden of Verses (1885)","url":"https://www.gutenberg.org/ebooks/136"},"rights":"pd","pd":"published 1885; Stevenson died 1894; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-stevenson-to-any-reader","title":"To Any Reader","by":"Robert Louis Stevenson","year":1885,"trad":["all"],"type":"poem","occasion":["home","celebration"],"text":"As from the house your mother sees\nYou playing round the garden trees,\nSo you may see, if you will look\nThrough the windows of this book,\nAnother child, far, far away,\nAnd in another garden, play.\nBut do not think you can at all,\nBy knocking on the window, call\nThat child to hear you. He intent\nIs all on his play-business bent.\nHe does not hear, he will not look,\nNor yet be lured out of this book.\nFor, long ago, the truth to say,\nHe has grown up and gone away,\nAnd it is but a child of air\nThat lingers in the garden there.","note":"Read aloud with children at bedtime or at home.","voice":"brian","source":{"name":"A Child's Garden of Verses (1885)","url":"https://www.gutenberg.org/ebooks/136"},"rights":"pd","pd":"published 1885; Stevenson died 1894; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-manyoshu-love-is-all","title":"Love Is All (from the Manyoshu)","by":"Traditional (Manyoshu)","tr":"Basil Hall Chamberlain","year":759,"trad":["all"],"type":"poem","occasion":["wedding"],"text":"Where in spring the sweetest flowers\nFill Mount Kaminabi's bowers,\nWhere in autumn dyed with red,\nEach ancient maple rears its head,\nAnd Aska's flood, with sedges lin'd,\nAs a belt the mound doth bind: There see my heart, a reed that sways,\nNor aught but love's swift stream obeys,\nAnd now, if like the dew, dear maid,\nLife must fade, then let it fade: My secret love is not in vain,\nFor thou lov'st me back again.","note":"Read at a wedding, an anniversary, or any celebration of love.","voice":"brian","source":{"name":"Japanese Literature (1900), Classical Poetry of Japan","url":"https://www.gutenberg.org/ebooks/19264"},"rights":"pd","pd":"published 759; translation by Chamberlain, published 759; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-okura-recollections-of-my-children","title":"Recollections of My Children (from the Manyoshu)","by":"Yamanoue no Okura","tr":"Basil Hall Chamberlain","year":759,"trad":["all"],"type":"poem","occasion":["home","birth"],"text":"Ne'er a melon can I eat,\nBut calls to mind my children dear;\nNe'er a chestnut crisp and sweet,\nBut makes the lov'd ones seem more near.\nWhence did they come, my life to cheer?\nBefore mine eyes they seem to sweep,\nSo that I may not even sleep.\nWhat use to me the gold and silver hoard?\nWhat use to me the gems most rich and rare?\nBrighter by far, aye! bright beyond compare,\nThe joys my children to my heart afford!","note":"Read to honor the love of parents for their children.","voice":"brian","source":{"name":"Japanese Literature (1900), Classical Poetry of Japan","url":"https://www.gutenberg.org/ebooks/19264"},"rights":"pd","pd":"published 759; translation by Chamberlain, published 759; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-okura-so-young","title":"So Young (from the Manyoshu)","by":"Yamanoue no Okura (attributed)","tr":"Basil Hall Chamberlain","year":759,"trad":["all"],"type":"poem","occasion":["grief"],"text":"So young, so young! he cannot know the way: On Hades' porter I'll a bribe bestow,\nThat on his shoulders the dear infant may\nBe safely carried to the realms below.","note":"Read gently for parents grieving a child.","voice":"brian","source":{"name":"Japanese Literature (1900), Classical Poetry of Japan","url":"https://www.gutenberg.org/ebooks/19264"},"rights":"pd","pd":"published 759; translation by Chamberlain, published 759; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-manyoshu-spring-and-autumn","title":"Spring and Autumn (from the Manyoshu)","by":"Ohogimi","tr":"Basil Hall Chamberlain","year":759,"trad":["all"],"type":"poem","occasion":["season","nature"],"text":"When winter turns to spring,\nBirds that were songless make their songs resound,\nFlow'rs that were flow'rless cover all the ground;\nYet 'tis no perfect thing: I cannot walk, so tangled is each hill;\nSo thick the herbs I cannot pluck my fill.\nBut in the autumn-tide\nI cull the scarlet leaves and love them dear,\nAnd let the green leaves stay, with many a tear,\nAll on the fair hill-side: No time so sweet as that. Away! Away!\nAutumn's the time I fain would keep alway.","note":"Read to mark the turning of the seasons.","voice":"brian","source":{"name":"Japanese Literature (1900), Classical Poetry of Japan","url":"https://www.gutenberg.org/ebooks/19264"},"rights":"pd","pd":"published 759; translation by Chamberlain, published 759; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-li-po-mountains-summer-day","title":"In the Mountains on a Summer Day","by":"Li Po","tr":"Arthur Waley","year":1919,"trad":["all"],"type":"poem","occasion":["nature","peace","season"],"text":"Gently I stir a white feather fan,\nWith open shirt sitting in a green wood.\nI take off my cap and hang it on a jutting stone;\nA wind from the pine-trees trickles on my bare head.","note":"Read outdoors, on a walk, or at a gathering in nature.","voice":"brian","source":{"name":"More Translations from the Chinese (1919)","url":"https://www.gutenberg.org/ebooks/16500"},"rights":"pd","pd":"published 1919; translation by Waley, published 1919; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-po-chu-i-planting-bamboos","title":"Planting Bamboos","by":"Po Chu-i","tr":"Arthur Waley","year":1919,"trad":["all"],"type":"poem","occasion":["nature","home"],"text":"Unrewarded, my will to serve the State;\nAt my closed door autumn grasses grow.\nWhat could I do to ease a rustic heart?\nI planted bamboos, more than a hundred shoots.\nWhen I see their beauty, as they grow by the stream-side,\nI feel again as though I lived in the hills,\nAnd many a time on public holidays\nRound their railing I walk till night comes.\nDo not say that their roots are still weak,\nDo not say that their shade is still small;\nAlready I feel that both in garden and house\nDay by day a fresher air moves.\nBut most I love, lying near the window-side,\nTo hear in their branches the sound of the autumn-wind.","note":"Read outdoors, on a walk, or at a gathering in nature.","voice":"brian","source":{"name":"More Translations from the Chinese (1919)","url":"https://www.gutenberg.org/ebooks/16500"},"rights":"pd","pd":"published 1919; translation by Waley, published 1919; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-po-chu-i-early-oriole","title":"Hearing the Early Oriole","by":"Po Chu-i","tr":"Arthur Waley","year":1919,"trad":["all"],"type":"poem","occasion":["season","morning"],"text":"When the sun rose I was still lying in bed;\nAn early oriole sang on the roof of my house.\nFor a moment I thought of the Royal Park at dawn\nWhen the Birds of Spring greeted their Lord from his trees.\nI remembered the days when I served before the Throne\nPencil in hand, on duty at the Ch`eng1-ming;\nAt the height of spring, when I paused an instant from work,\nMorning and evening, was this the voice I heard?\nNow in my exile the oriole sings again\nIn the dreary stillness of Hsuun-yang town ...\nThe bird's note cannot really have changed;\nAll the difference lies in the listener's heart.\nIf he could but forget that he lives at the World's end,\nThe bird would sing as it sang in the Palace of old.","note":"Read to begin the day with a quiet moment.","voice":"brian","source":{"name":"More Translations from the Chinese (1919)","url":"https://www.gutenberg.org/ebooks/16500"},"rights":"pd","pd":"published 1919; translation by Waley, published 1919; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-po-chu-i-pine-trees","title":"The Pine-Trees in the Courtyard","by":"Po Chu-i","tr":"Arthur Waley","year":1919,"trad":["all"],"type":"poem","occasion":["nature","home"],"text":"Below the hall\nThe pine-trees grow in front of the steps,\nIrregularly scattered, not in ordered lines.\nSome are tall and some are low:\nThe tallest of them is six roods high;\nThe lowest but ten feet.\nThey are like wild things\nAnd no one knows who planted them.\nThey touch the walls of my blue-tiled house;\nTheir roots are sunk in the terrace of white sand.\nMorning and evening they are visited by the wind and moon;\nRain or fine, they are free from dust and mud.\nIn the gales of autumn they whisper a vague tune;\nFrom the suns of summer they yield a cool shade.\nAt the height of spring the fine evening rain\nFills their leaves with a load of hanging pearls.\nAt the year's end the time of great snow\nStamps their branches with a fret of glittering jade.\nOf the Four Seasons each has its own mood;\nAmong all the trees none is like another.\nLast year, when they heard I had bought this house,\nNeighbours mocked and the World called me mad,\nThat a whole family of twice ten souls\nShould move house for the sake of a few pines!\nNow that I have come to them, what have they given me?\nThey have only loosened the buckles of my care.\nYet even so, they are \"profitable friends,\"\nAnd fill my need of \"converse with wise men.\"\nYet when I consider how, still a man of the world,\nIn belt and cap I scurry through dirt and dust,\nFrom time to time my heart twinges with shame\nThat I am not fit to be master of my pines!\n\n\"profitable friends\" and three kinds of \"profitable pleasures\" are\ndescribed; the third of the latter being \"plenty of intelligent\ncompanions.\"","note":"Read outdoors, on a walk, or at a gathering in nature.","voice":"brian","source":{"name":"More Translations from the Chinese (1919)","url":"https://www.gutenberg.org/ebooks/16500"},"rights":"pd","pd":"published 1919; translation by Waley, published 1919; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-po-chu-i-old-age","title":"Old Age","by":"Po Chu-i","tr":"Arthur Waley","year":1919,"trad":["all"],"type":"poem","occasion":["celebration","dying"],"text":"We are growing old together, you and I,\nLet us ask ourselves, what is age like?\nThe dull eye is closed ere night comes;\nThe idle head, still uncombed at noon.\nPropped on a staff, sometimes a walk abroad;\nOr all day sitting with closed doors.\nOne dares not look in the mirror's polished face;\nOne cannot read small-letter books.\nDeeper and deeper, one's love of old friends;\nFewer and fewer, one's dealings with young men.\nOne thing only, the pleasure of idle talk,\nIs great as ever, when you and I meet.","note":"Read at a milestone birthday or a gathering honoring an elder.","voice":"brian","source":{"name":"More Translations from the Chinese (1919)","url":"https://www.gutenberg.org/ebooks/16500"},"rights":"pd","pd":"published 1919; translation by Waley, published 1919; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-po-chu-i-since-i-lay-ill","title":"Since I Lay Ill","by":"Po Chu-i","tr":"Arthur Waley","year":1919,"trad":["all"],"type":"poem","occasion":["healing"],"text":"Since I lay ill, how long has passed?\nAlmost a hundred heavy-hanging days.\nThe maids have learnt to gather my medicine-herbs;\nThe dog no longer barks when the doctor comes.\nThe jars in my cellar are plastered deep with mould;\nMy singer's carpets are half crumbled to dust.\nHow can I bear, when the Earth renews her light,\nTo watch from a pillow the beauty of Spring unfold?","note":"Read for someone recovering from illness.","voice":"brian","source":{"name":"More Translations from the Chinese (1919)","url":"https://www.gutenberg.org/ebooks/16500"},"rights":"pd","pd":"published 1919; translation by Waley, published 1919; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-po-chu-i-resignation","title":"Resignation","by":"Po Chu-i","tr":"Arthur Waley","year":1919,"trad":["all"],"type":"poem","occasion":["dying","peace"],"text":"Keep off your thoughts from things that are past and done;\nFor thinking of the past wakes regret and pain.\nKeep off your thoughts from thinking what will happen;\nTo think of the future fills one with dismay.\nBetter by day to sit like a sack in your chair;\nBetter by night to lie a stone in your bed.\nWhen food comes, then open your mouth;\nWhen sleep comes, then close your eyes.","note":"Read at a milestone birthday or a gathering honoring an elder.","voice":"brian","source":{"name":"More Translations from the Chinese (1919)","url":"https://www.gutenberg.org/ebooks/16500"},"rights":"pd","pd":"published 1919; translation by Waley, published 1919; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-greek-on-a-baby","title":"On a Baby","by":"Traditional (Greek Anthology)","tr":"J. W. Mackail","year":1890,"trad":["all"],"type":"poem","occasion":["grief"],"text":"Me a baby that was just tasting life heaven snatched away, I know not whether for good or for evil; insatiable Death, why hast thou snatched me cruelly in infancy? why hurriest thou? Are we not all thine in the end?","note":"Read gently for parents grieving a child.","voice":"brian","source":{"name":"Select Epigrams from the Greek Anthology (Mackail)","url":"https://www.gutenberg.org/ebooks/2378"},"rights":"pd","pd":"published 1890; translation by Mackail, published 1890; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-greek-on-a-child-of-five","title":"On a Child of Five","by":"Lucian","tr":"J. W. Mackail","year":1890,"trad":["all"],"type":"poem","occasion":["grief"],"text":"Me Callimachus, a five-years-old child whose spirit knew not grief, pitiless Death snatched away; but weep thou not for me; for little was my share in life, and little in life's ills.","note":"Read gently for parents grieving a child.","voice":"brian","source":{"name":"Select Epigrams from the Greek Anthology (Mackail)","url":"https://www.gutenberg.org/ebooks/2378"},"rights":"pd","pd":"published 1890; translation by Mackail, published 1890; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-greek-on-a-young-wife","title":"On a Young Wife","by":"Traditional (Greek Anthology)","tr":"J. W. Mackail","year":1890,"trad":["all"],"type":"poem","occasion":["grief","funeral"],"text":"To his wife Paulina, holy of life and blameless, who died at nineteen years, Andronicus the physician paying memorial placed this witness the last of all.","note":"Shared with someone carrying fresh grief.","voice":"brian","source":{"name":"Select Epigrams from the Greek Anthology (Mackail)","url":"https://www.gutenberg.org/ebooks/2378"},"rights":"pd","pd":"published 1890; translation by Mackail, published 1890; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-greek-on-a-dead-friend","title":"On a Dead Friend","by":"Traditional (Greek Anthology)","tr":"J. W. Mackail","year":1890,"trad":["all"],"type":"poem","occasion":["grief"],"text":"This little stone, good Sabinus, is the record of our great friendship; ever will I require thee; and thou, if it is permitted, drink not among the dead of the water of Lethe for me.","note":"Shared with someone carrying fresh grief.","voice":"brian","source":{"name":"Select Epigrams from the Greek Anthology (Mackail)","url":"https://www.gutenberg.org/ebooks/2378"},"rights":"pd","pd":"published 1890; translation by Mackail, published 1890; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-greek-on-a-favourite-dog","title":"On a Favourite Dog","by":"Traditional (Greek Anthology)","tr":"J. W. Mackail","year":1890,"trad":["all"],"type":"poem","occasion":["grief"],"text":"Thou who passest on the path, if haply thou dost mark this monument, laugh not, I pray thee, though it is a dog's grave; tears fell for me, and the dust was heaped above me by a master's hands, who likewise engraved these words on my tomb.","note":"Read when saying goodbye to a beloved animal companion.","voice":"brian","source":{"name":"Select Epigrams from the Greek Anthology (Mackail)","url":"https://www.gutenberg.org/ebooks/2378"},"rights":"pd","pd":"published 1890; translation by Mackail, published 1890; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-greek-the-dead-scholar","title":"The Dead Scholar (Heraclitus)","by":"Callimachus","tr":"J. W. Mackail","year":1890,"trad":["all"],"type":"poem","occasion":["grief","funeral"],"text":"One told me of thy fate, Heraclitus, and wrung me to tears, and I remembered how often both of us let the sun sink as we talked; but thou, methinks, O friend from Halicarnassus, art ashes long and long ago; yet thy nightingale-notes live, whereon Hades the ravisher of all things shall not lay his hand.","note":"Read in memory of a friend of long talks and shared days.","voice":"brian","source":{"name":"Select Epigrams from the Greek Anthology (Mackail)","url":"https://www.gutenberg.org/ebooks/2378"},"rights":"pd","pd":"published 1890; translation by Mackail, published 1890; US public domain (published 1930 or earlier)","denom":[]},{"id":"poem-greek-species-aeternitatis","title":"Species Aeternitatis","by":"Ptolemaeus","tr":"J. W. Mackail","year":1890,"trad":["all"],"type":"poem","occasion":["evening","nature"],"text":"I know that I am mortal, and ephemeral; but when I scan the multitudinous circling spirals of the stars, no longer do I touch earth with my feet, but sit with Zeus himself, and take my fill of the ambrosial food of gods.","note":"Read in the evening as the day comes to rest.","voice":"brian","source":{"name":"Select Epigrams from the Greek Anthology (Mackail)","url":"https://www.gutenberg.org/ebooks/2378"},"rights":"pd","pd":"published 1890; translation by Mackail, published 1890; US public domain (published 1930 or earlier)","denom":[]}];
